package com.dsaroadmap.config;

import com.dsaroadmap.dto.ApiDtos.*;
import com.dsaroadmap.model.*;
import com.dsaroadmap.repository.*;
import com.dsaroadmap.service.AdminService;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.*;
import org.springframework.security.crypto.password.PasswordEncoder;

@Configuration
public class SeedDataConfig {
    @Bean CommandLineRunner seedData(@Value("${app.seed}") boolean enabled, ConceptRepository concepts, UserRepository users, PasswordEncoder encoder, AdminService admin) {
        return args -> {
            if (!enabled || concepts.count() > 0) return;
            User administrator=new User();administrator.setName("Roadmap Admin");administrator.setEmail("admin@dsaroadmap.dev");administrator.setPasswordHash(encoder.encode("Admin@12345"));administrator.setRole(Role.ADMIN);users.save(administrator);
            User learner=new User();learner.setName("Demo Learner");learner.setEmail("learner@dsaroadmap.dev");learner.setPasswordHash(encoder.encode("Learner@12345"));learner.setRole(Role.STUDENT);users.save(learner);

            Long arrays=admin.createConcept(new ConceptRequest("Arrays & Hashing","Master lookups, prefix sums, intervals, and the patterns hiding inside everyday array problems.","Brackets",1,true)).id();
            Long pointers=admin.createConcept(new ConceptRequest("Two Pointers","Turn nested loops into elegant linear scans by coordinating positions.","MoveHorizontal",2,true)).id();
            Long lists=admin.createConcept(new ConceptRequest("Linked Lists","Build intuition for pointer rewiring, fast-slow traversal, and in-place operations.","Workflow",3,true)).id();
            Long trees=admin.createConcept(new ConceptRequest("Trees","Learn recursive structure, traversals, binary search trees, and balanced reasoning.","Network",4,true)).id();
            Long graphs=admin.createConcept(new ConceptRequest("Graphs","Navigate connected worlds with BFS, DFS, shortest paths, and topological order.","Share2",5,true)).id();
            Long dp=admin.createConcept(new ConceptRequest("Dynamic Programming","Trade repeated work for state. Start small, recognize transitions, then optimize.","Layers3",6,true)).id();

            create(admin,arrays,"Two Sum",Difficulty.EASY,20,"Given an integer array nums and a target, return the indices of the two numbers that add up to target. Exactly one valid answer exists, and the same element cannot be used twice.","2 ≤ nums.length ≤ 10⁴\n-10⁹ ≤ nums[i], target ≤ 10⁹","nums = [2,7,11,15], target = 9\nOutput: [0,1]",Set.of("Google","Amazon","Meta"),Set.of("Array","Hash Map"),"https://leetcode.com/problems/two-sum/",twoSumSolutions());
            create(admin,arrays,"Maximum Subarray",Difficulty.MEDIUM,25,"Find the contiguous subarray with the largest sum and return its sum.","1 ≤ nums.length ≤ 10⁵","nums = [-2,1,-3,4,-1,2,1,-5,4]\nOutput: 6",Set.of("Microsoft","Amazon"),Set.of("Array","Kadane's Algorithm","Dynamic Programming"),"https://leetcode.com/problems/maximum-subarray/",pythonSolution("Kadane's algorithm keeps the best subarray ending at each position.","def max_sub_array(nums):\n    current = best = nums[0]\n    for value in nums[1:]:\n        current = max(value, current + value)\n        best = max(best, current)\n    return best","O(n)","O(1)"));
            create(admin,arrays,"Product of Array Except Self",Difficulty.MEDIUM,30,"Return an array where each answer[i] is the product of every element except nums[i], without division.","2 ≤ nums.length ≤ 10⁵","nums = [1,2,3,4]\nOutput: [24,12,8,6]",Set.of("Amazon","Apple"),Set.of("Array","Prefix Product"),"https://leetcode.com/problems/product-of-array-except-self/",List.of());
            create(admin,pointers,"Valid Palindrome",Difficulty.EASY,15,"Determine whether a phrase is a palindrome after removing non-alphanumeric characters and ignoring case.","1 ≤ s.length ≤ 2 × 10⁵","s = 'A man, a plan, a canal: Panama'\nOutput: true",Set.of("Meta","Microsoft"),Set.of("String","Two Pointers"),"https://leetcode.com/problems/valid-palindrome/",List.of());
            create(admin,pointers,"3Sum",Difficulty.MEDIUM,35,"Return every unique triplet whose values sum to zero.","3 ≤ nums.length ≤ 3000","nums = [-1,0,1,2,-1,-4]\nOutput: [[-1,-1,2],[-1,0,1]]",Set.of("Meta","Amazon"),Set.of("Array","Sorting","Two Pointers"),"https://leetcode.com/problems/3sum/",List.of());
            create(admin,lists,"Reverse Linked List",Difficulty.EASY,20,"Reverse a singly linked list and return its new head.","0 ≤ node count ≤ 5000","head = [1,2,3,4,5]\nOutput: [5,4,3,2,1]",Set.of("Google","Apple"),Set.of("Linked List","Recursion"),"https://leetcode.com/problems/reverse-linked-list/",List.of());
            create(admin,lists,"Linked List Cycle",Difficulty.EASY,20,"Determine whether a linked list contains a cycle using constant extra space.","0 ≤ node count ≤ 10⁴","head = [3,2,0,-4], pos = 1\nOutput: true",Set.of("Amazon","Microsoft"),Set.of("Linked List","Fast & Slow Pointers"),"https://leetcode.com/problems/linked-list-cycle/",List.of());
            create(admin,trees,"Validate Binary Search Tree",Difficulty.MEDIUM,30,"Determine whether a binary tree satisfies the strict binary search tree ordering invariant.","1 ≤ node count ≤ 10⁴","root = [2,1,3]\nOutput: true",Set.of("Amazon","Bloomberg"),Set.of("Tree","DFS","BST"),"https://leetcode.com/problems/validate-binary-search-tree/",List.of());
            create(admin,trees,"Binary Tree Level Order Traversal",Difficulty.MEDIUM,25,"Return node values level by level from left to right.","0 ≤ node count ≤ 2000","root = [3,9,20,null,null,15,7]\nOutput: [[3],[9,20],[15,7]]",Set.of("Meta","Microsoft"),Set.of("Tree","BFS"),"https://leetcode.com/problems/binary-tree-level-order-traversal/",List.of());
            create(admin,graphs,"Number of Islands",Difficulty.MEDIUM,35,"Count connected components of land in a two-dimensional grid.","1 ≤ rows, cols ≤ 300","grid = [[1,1,0],[1,0,0],[0,0,1]]\nOutput: 2",Set.of("Amazon","Google"),Set.of("Graph","DFS","BFS","Matrix"),"https://leetcode.com/problems/number-of-islands/",List.of());
            create(admin,graphs,"Course Schedule",Difficulty.MEDIUM,40,"Determine whether every course can be completed given prerequisite pairs.","1 ≤ numCourses ≤ 2000","numCourses = 2, prerequisites = [[1,0]]\nOutput: true",Set.of("Google","Meta"),Set.of("Graph","Topological Sort"),"https://leetcode.com/problems/course-schedule/",List.of());
            create(admin,dp,"Climbing Stairs",Difficulty.EASY,20,"Count distinct ways to reach the top when each move climbs one or two steps.","1 ≤ n ≤ 45","n = 5\nOutput: 8",Set.of("Amazon","Adobe"),Set.of("Dynamic Programming","Math"),"https://leetcode.com/problems/climbing-stairs/",List.of());
            create(admin,dp,"Longest Increasing Subsequence",Difficulty.MEDIUM,45,"Return the length of the longest strictly increasing subsequence.","1 ≤ nums.length ≤ 2500","nums = [10,9,2,5,3,7,101,18]\nOutput: 4",Set.of("Microsoft","Google"),Set.of("Dynamic Programming","Binary Search"),"https://leetcode.com/problems/longest-increasing-subsequence/",List.of());
        };
    }

    private void create(AdminService admin,Long concept,String name,Difficulty difficulty,int minutes,String description,String constraints,String examples,Set<String> companies,Set<String> topics,String url,List<SolutionRequest> solutions){
        admin.createProblem(new ProblemRequest(concept,name,description,difficulty,minutes,constraints,null,null,examples,0,true,companies,topics,List.of(new LinkRequest(Platform.LEETCODE,url),new LinkRequest(Platform.GEEKSFORGEEKS,"https://www.geeksforgeeks.org/search/")),List.of(new VideoRequest(name+" — visual explanation","https://www.youtube.com/results?search_query="+name.replace(' ','+'),"Roadmap Picks")),solutions));
    }
    private List<SolutionRequest> pythonSolution(String approach,String code,String time,String space){return List.of(new SolutionRequest(Language.PYTHON,code,approach,"Walk through the input once while maintaining only the state needed for the next decision.",time,space,null,null));}
    private List<SolutionRequest> twoSumSolutions(){String approach="Scan once and store each value's index in a hash map. Before inserting the current value, check whether its complement has already appeared.";String explanation="At index i, the map contains exactly the elements to the left. If target - nums[i] is present, those two indices form the answer. Otherwise, remember nums[i] and continue.";return List.of(
        new SolutionRequest(Language.C,"#include <stdlib.h>\n\nint* twoSum(int* nums, int n, int target, int* returnSize) {\n    int *answer = malloc(2 * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        for (int j = i + 1; j < n; j++) {\n            if (nums[i] + nums[j] == target) {\n                answer[0] = i; answer[1] = j; *returnSize = 2;\n                return answer;\n            }\n        }\n    }\n    *returnSize = 0; return answer;\n}","Check each pair directly; the C version favors a compact dependency-free implementation.",explanation,"O(n²)","O(1)","For [2,7,11,15], compare 2 with 7 and immediately find 9.","for each i:\n  for each j after i:\n    if nums[i] + nums[j] == target: return [i,j]"),
        new SolutionRequest(Language.CPP,"#include <unordered_map>\n#include <vector>\nusing namespace std;\n\nvector<int> twoSum(vector<int>& nums, int target) {\n    unordered_map<int, int> seen;\n    for (int i = 0; i < (int)nums.size(); ++i) {\n        int need = target - nums[i];\n        if (seen.count(need)) return {seen[need], i};\n        seen[nums[i]] = i;\n    }\n    return {};\n}",approach,explanation,"O(n)","O(n)",null,null),
        new SolutionRequest(Language.JAVA,"import java.util.HashMap;\nimport java.util.Map;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        Map<Integer, Integer> seen = new HashMap<>();\n        for (int i = 0; i < nums.length; i++) {\n            int need = target - nums[i];\n            if (seen.containsKey(need)) return new int[]{seen.get(need), i};\n            seen.put(nums[i], i);\n        }\n        return new int[0];\n    }\n}",approach,explanation,"O(n)","O(n)",null,null),
        new SolutionRequest(Language.PYTHON,"def two_sum(nums: list[int], target: int) -> list[int]:\n    seen = {}\n    for index, value in enumerate(nums):\n        complement = target - value\n        if complement in seen:\n            return [seen[complement], index]\n        seen[value] = index\n    return []",approach,explanation,"O(n)","O(n)",null,null),
        new SolutionRequest(Language.KOTLIN,"class Solution {\n    fun twoSum(nums: IntArray, target: Int): IntArray {\n        val seen = mutableMapOf<Int, Int>()\n        nums.forEachIndexed { index, value ->\n            val complement = target - value\n            seen[complement]?.let { return intArrayOf(it, index) }\n            seen[value] = index\n        }\n        return intArrayOf()\n    }\n}",approach,explanation,"O(n)","O(n)",null,null));}
}
